nextflow_process {

    name "Test Process SALTSHAKER_CLASSIFY"
    script "../main.nf"
    process "SALTSHAKER_CLASSIFY"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "saltshaker"
    tag "saltshaker/call"
    tag "saltshaker/classify"

    setup {
        run("SALTSHAKER_CALL") {
            script "../../call/main.nf"
            process {
            """
            input[0] = [
                [ id:'test' ],
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/mitosalt/test_mitosalt.breakpoint', checkIfExists: true),
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/mitosalt/test_mitosalt.cluster', checkIfExists: true),
            ]

            input[1] = [
                [ id:'hg38' ],
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/human_mt_rCRS.fasta', checkIfExists: true),
            ]

            input[2] = 15
            input[3] = 0.01
            input[4] = 16569
            input[5] = 16081
            input[6] = 407
            input[7] = 5730
            input[8] = 5763
            """
        }
        }
    }

    test("classify - vcf") {

        when {
            params {
                module_args = '--blacklist --vcf --dominant-fraction 0.5 --radius 600 --high-het 10 --multiple-threshold 5 --noise 0.3'
            }
            process {
                """
                input[0] = SALTSHAKER_CALL.out.call
                input[1] = "MT"
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out),
                ).match() }

            )
        }

    }

    test("classify - vcf - stub") {

        options "-stub"

        when {
            params {
                module_args = '--blacklist --vcf --dominant-fraction 0.5 --radius 600 --high-het 10 --multiple-threshold 5 --noise 0.3'
            }
            process {
                """
                input[0] = SALTSHAKER_CALL.out.call
                input[1] = "MT"
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out),
                ).match() }
            )
        }

    }

    test("classify - defaults") {

        when {
            params {
                module_args = ''
            }
            process {
                """
                input[0] = SALTSHAKER_CALL.out.call
                input[1] = "MT"
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out),
                ).match() }

            )
        }

    }

    test("classify - defaults - stub") {

        options "-stub"

        when {
            params {
                module_args = ''
            }
            process {
                """
                input[0] = SALTSHAKER_CALL.out.call
                input[1] = "MT"
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out),
                ).match() }
            )
        }

    }

}

